SELECT id, out_trade_no AS outTradeNo, total_amount AS totalAmount, account_amount AS accountAmount, pay_status AS payStatus, create_time AS createTime FROM order_pay WHERE pay_status = 1
AND create_time >= #{startDate}
AND create_time <= #{endDate}
ORDER BY create_time ASC

SELECT id, gross_amount_vnd AS grossAmountVnd, withheld_tax_vnd AS withheldTaxVnd, net_amount_vnd AS netAmountVnd, status, create_time AS createTime, update_time AS updateTime FROM author_withdrawal_request WHERE status IN ('APPROVED', 'PAID')
AND create_time >= #{startDate}
AND create_time <= #{endDate}
ORDER BY create_time ASC

SELECT id, buy_amount AS buyAmount, create_time AS createTime FROM user_buy_record
AND create_time >= #{startDate}
AND create_time <= #{endDate}
ORDER BY create_time ASC
